// SetCDCEquipamentos removes all previously related items of the
// centro_de_custo replacing them completely with the passed
// in related items, optionally inserting them as new records.
// Sets o.R.CDC's CDCEquipamentos accordingly.
// Replaces o.R.CDCEquipamentos with related.
// Sets related.R.CDC's CDCEquipamentos accordingly.
func (o *CentroDeCusto) SetCDCEquipamentos(ctx context.Context, exec boil.ContextExecutor, insert bool, related ...*Equipamento) error {
	query := "update `equipamento` set `cdc_id` = null where `cdc_id` = ?"
	values := []interface{}{o.CDCID}
	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, query)
		fmt.Fprintln(writer, values)
	}
	_, err := exec.ExecContext(ctx, query, values...)
	if err != nil {
		return errors.Wrap(err, "failed to remove relationships before set")
	}

	if o.R != nil {
		for _, rel := range o.R.CDCEquipamentos {
			queries.SetScanner(&rel.CDCID, nil)
			if rel.R == nil {
				continue
			}

			rel.R.CDC = nil
		}
		o.R.CDCEquipamentos = nil
	}

	return o.AddCDCEquipamentos(ctx, exec, insert, related...)
}

// RemoveCDCEquipamentos relationships from objects passed in.
// Removes related items from R.CDCEquipamentos (uses pointer comparison, removal does not keep order)
// Sets related.R.CDC.
func (o *CentroDeCusto) RemoveCDCEquipamentos(ctx context.Context, exec boil.ContextExecutor, related ...*Equipamento) error {
	if len(related) == 0 {
		return nil
	}

	var err error
	for _, rel := range related {
		queries.SetScanner(&rel.CDCID, nil)
		if rel.R != nil {
			rel.R.CDC = nil
		}
		if _, err = rel.Update(ctx, exec, boil.Whitelist("cdc_id")); err != nil {
			return err
		}
	}
	if o.R == nil {
		return nil
	}

	for _, rel := range related {
		for i, ri := range o.R.CDCEquipamentos {
			if rel != ri {
				continue
			}

			ln := len(o.R.CDCEquipamentos)
			if ln > 1 && i < ln-1 {
				o.R.CDCEquipamentos[i] = o.R.CDCEquipamentos[ln-1]
			}
			o.R.CDCEquipamentos = o.R.CDCEquipamentos[:ln-1]
			break
		}
	}

	return nil
}

